<?php require 'config.php';$rows=$db->query('SELECT * FROM events ORDER BY event_date');?><h1>Events</h1><form action="save.php" method="post" enctype="multipart/form-data"><input name="title" required placeholder="Event title"><input type="date" name="event_date" required><input type="file" name="poster" accept="image/jpeg,image/png,image/webp"><button>Add event</button></form><?php while($e=$rows->fetch_assoc()):?><article><h2><?=htmlspecialchars($e['title'])?></h2><p><?=htmlspecialchars($e['event_date'])?></p><?php if($e['poster']):?><img width="180" src="uploads/<?=rawurlencode($e['poster'])?>" alt="Event poster"><?php endif;?></article><?php endwhile;?>